mapper.select:
SELECT MIN(recent.id)
FROM (
    SELECT message.id
    FROM diet_messages message
    INNER JOIN diet_sessions session
            ON session.id = message.session_id
           AND session.user_id = #{userId}
    WHERE message.session_id = #{sessionId}
    ORDER BY message.id DESC
    LIMIT #{recentLimit}
) recent

SELECT message.id,
       message.session_id,
       message.role,
       message.content,
       message.intent,
       message.agent_trace_id,
       message.created_at
FROM diet_messages message
INNER JOIN diet_sessions session
        ON session.id = message.session_id
       AND session.user_id = #{userId}
WHERE message.session_id = #{sessionId}
  AND message.id > #{afterMessageId}
  AND message.id < #{beforeMessageId}
ORDER BY message.id ASC
LIMIT #{limit}

mapper.update:
UPDATE diet_user_memory
SET active = 0,
    updated_at = NOW()
WHERE id = #{memoryId}
  AND user_id = #{userId}
  AND active = 1
